// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));

        bool ok;
        string memory v;
        try c.version() returns (string memory s) {
            ok = true;
            v = s;
        } catch {
            ok = false;
            v = "";
        }

        bytes memory vb = bytes(v);
        bool hasDot = false;
        for (uint i = 0; i < vb.length; i++) {
            if (vb[i] == ".") { hasDot = true; break; }
        }

        assertTrue(!ok || hasDot);
    }
}
